#!/usr/bin/env python3
import datetime, hashlib, json, os, sys, time, uuid
from pathlib import Path
sys.path.insert(0, str(Path.cwd() / 'scripts/aws'))
from aws_cli import observe

ACCOUNT='000000000000'
REGION='us-east-1'
PREFIX='stackd-sns-cwctx-'+uuid.uuid4().hex[:12]
OUT=Path('testdata/aws/sns/encryption_cloudwatch_source.json')
ENV=dict(os.environ,AWS_DEFAULT_REGION=REGION,AWS_REGION=REGION,AWS_MAX_ATTEMPTS='2',AWS_PAGER='')
START=time.time()
TOPIC='arn:aws:sns:'+REGION+':'+ACCOUNT+':'+PREFIX
ALARM=PREFIX+'-alarm'
ALARM_ARN='arn:aws:cloudwatch:'+REGION+':'+ACCOUNT+':alarm:'+ALARM
CAP={'account':ACCOUNT,'region':REGION,'prefix':PREFIX,'started_ms':int(START*1000),'source_references':['https://docs.aws.amazon.com/sns/latest/dg/sns-key-management.html','https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/API_SetAlarmState.html'],'source_revisions':{'stackd':'6c8e6a39e279a7bd64483c78d788cf5fc2a2e9cf','prior_native_fixtures':['testdata/aws/sns/encryption.json','testdata/aws/sns/encryption_service_sources.json','testdata/aws/cloudwatch/sns_publications.json']},'observations':[],'receipts':[],'windows':[],'cleanup':[],'cloudtrail':{'events':[],'lookups':[]},'owned_resources':{},'limitations':['One standard topic, one raw unencrypted SQS subscriber and one metric alarm in us-east-1. SetAlarmState exercises an actual alarm action, not a metric evaluator; no metric data is published.','Only CloudWatch receives service-principal KMS GenerateDataKey/Decrypt rights. Its grant is topic encryption-context bound, with no SNS service grant. This is a positive publication/context capture, not a negative KMS-principal authorization matrix.','CloudTrail management event-history availability is asynchronous; absence is bounded by recorded poll window. No changes to any standing trail or organization settings.']}
R=CAP['owned_resources']

def ms(): return int(time.time()*1000)
def save(): OUT.write_text(json.dumps(CAP,indent=2)+'\n')
def call(label,service,operation,args=None,strict=True,cleanup=False):
    item={'label':label,'service':service,'operation':operation,'input':args or {},'request_started_ms':ms()}
    try: result=observe(service,operation,args,ENV)
    except Exception as e:
        item.update(transport_error=str(e),response_observed_ms=ms()); CAP['cleanup' if cleanup else 'observations'].append(item); save()
        if strict: raise
        return {'code':'TransportError','message':str(e)}
    item.update(result=result,response_observed_ms=ms()); CAP['cleanup' if cleanup else 'observations'].append(item); save()
    if strict and result['code']!='Success': raise RuntimeError(label+': '+json.dumps(result))
    return result.get('output',{}) if strict else result

def policy(statements): return json.dumps({'Version':'2012-10-17','Statement':statements})
def receive(round_name,reason,seconds):
    started=ms(); deadline=time.monotonic()+seconds; found=False
    while time.monotonic()<deadline and not found:
        out=call('receive-'+round_name,'sqs','receive-message',{'QueueUrl':R['queue']['url'],'WaitTimeSeconds':5,'MaxNumberOfMessages':10,'MessageAttributeNames':['All'],'MessageSystemAttributeNames':['All']})
        for message in out.get('Messages',[]):
            decoded=json.loads(message['Body'])
            correlated=decoded.get('AlarmArn')==ALARM_ARN and decoded.get('AlarmName')==ALARM and decoded.get('AWSAccountId')==ACCOUNT and decoded.get('NewStateValue')=='ALARM' and decoded.get('NewStateReason')==reason
            CAP['receipts'].append({'round':round_name,'observed_ms':ms(),'message':message,'decoded_notification':decoded,'correlated':correlated})
            call('delete-receipt-'+round_name,'sqs','delete-message',{'QueueUrl':R['queue']['url'],'ReceiptHandle':message['ReceiptHandle']})
            found=found or correlated
    CAP['windows'].append({'kind':'consumer-receipt','round':round_name,'started_ms':started,'ended_ms':ms(),'maximum_seconds':seconds,'correlated_receipt':found}); save()
    return found

try:
    CAP['identity']=call('identity-before-mutation','sts','get-caller-identity')
    if CAP['identity']['Account']!=ACCOUNT: raise RuntimeError('Unexpected account; mutations forbidden')
    statements=[{'Sid':'OwnerAdministration','Effect':'Allow','Principal':{'AWS':'arn:aws:iam::'+ACCOUNT+':root'},'Action':'kms:*','Resource':'*'},{'Sid':'CloudWatchPublisher','Effect':'Allow','Principal':{'Service':'cloudwatch.amazonaws.com'},'Action':['kms:GenerateDataKey','kms:Decrypt'],'Resource':'*','Condition':{'StringEquals':{'kms:EncryptionContext:aws:sns:topicArn':TOPIC}}}]
    R['key']=call('create-key','kms','create-key',{'Description':PREFIX,'Policy':policy(statements),'Tags':[{'TagKey':'stackd-probe','TagValue':PREFIX}]})['KeyMetadata']
    call('read-key-policy','kms','get-key-policy',{'KeyId':R['key']['KeyId'],'PolicyName':'default'})
    R['topic']=call('create-topic','sns','create-topic',{'Name':PREFIX,'Attributes':{'KmsMasterKeyId':R['key']['Arn']}})['TopicArn']
    assert R['topic']==TOPIC
    call('topic-policy','sns','set-topic-attributes',{'TopicArn':TOPIC,'AttributeName':'Policy','AttributeValue':policy([{'Effect':'Allow','Principal':{'Service':'cloudwatch.amazonaws.com'},'Action':'sns:Publish','Resource':TOPIC,'Condition':{'ArnEquals':{'aws:SourceArn':ALARM_ARN},'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])})
    R['queue']={'name':PREFIX+'-collector','url':call('create-queue','sqs','create-queue',{'QueueName':PREFIX+'-collector','Attributes':{'SqsManagedSseEnabled':'false'}})['QueueUrl']}
    R['queue']['arn']=call('read-queue','sqs','get-queue-attributes',{'QueueUrl':R['queue']['url'],'AttributeNames':['QueueArn','SqsManagedSseEnabled']})['Attributes']['QueueArn']
    call('queue-policy','sqs','set-queue-attributes',{'QueueUrl':R['queue']['url'],'Attributes':{'Policy':policy([{'Effect':'Allow','Principal':{'Service':'sns.amazonaws.com'},'Action':'sqs:SendMessage','Resource':R['queue']['arn'],'Condition':{'ArnEquals':{'aws:SourceArn':TOPIC},'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])}})
    R['subscription']=call('subscribe-raw','sns','subscribe',{'TopicArn':TOPIC,'Protocol':'sqs','Endpoint':R['queue']['arn'],'Attributes':{'RawMessageDelivery':'true'},'ReturnSubscriptionArn':True})['SubscriptionArn']
    call('verify-topic-encryption-policy','sns','get-topic-attributes',{'TopicArn':TOPIC})
    call('verify-raw-subscription','sns','get-subscription-attributes',{'SubscriptionArn':R['subscription']})
    call('create-alarm','cloudwatch','put-metric-alarm',{'AlarmName':ALARM,'AlarmDescription':PREFIX+' encrypted SNS source context capture','ActionsEnabled':True,'AlarmActions':[TOPIC],'Namespace':PREFIX,'MetricName':'NeverPublished','Statistic':'Average','Period':300,'EvaluationPeriods':1,'Threshold':1,'ComparisonOperator':'GreaterThanThreshold','TreatMissingData':'ignore','Tags':[{'Key':'stackd-probe','Value':PREFIX}]})
    R['alarm']={'name':ALARM,'arn':ALARM_ARN}
    call('verify-alarm','cloudwatch','describe-alarms',{'AlarmNames':[ALARM]})
    for attempt in range(3):
        round_name='attempt-'+str(attempt+1)
        reason=PREFIX+' '+round_name+' nonce '+uuid.uuid4().hex
        call('set-ok-'+round_name,'cloudwatch','set-alarm-state',{'AlarmName':ALARM,'StateValue':'OK','StateReason':PREFIX+' prepare '+round_name})
        call('set-alarm-'+round_name,'cloudwatch','set-alarm-state',{'AlarmName':ALARM,'StateValue':'ALARM','StateReason':reason})
        found=receive(round_name,reason,75)
        call('alarm-history-'+round_name,'cloudwatch','describe-alarm-history',{'AlarmName':ALARM,'MaxRecords':100})
        if found: break
    if not any(r['correlated'] for r in CAP['receipts']): CAP['limitations'].append('No correlated receipt in three recorded 75-second receive windows; action history preserves any service publication failures.')
    CAP['delivery_finished_ms']=ms(); save()
except Exception as e:
    CAP['failure']=str(e); save()
finally:
    if 'alarm' in R:
        call('delete-alarm','cloudwatch','delete-alarms',{'AlarmNames':[ALARM]},strict=False,cleanup=True)
        call('verify-alarm-absent','cloudwatch','describe-alarms',{'AlarmNames':[ALARM]},strict=False,cleanup=True)
    if 'subscription' in R:
        call('unsubscribe','sns','unsubscribe',{'SubscriptionArn':R['subscription']},strict=False,cleanup=True)
        call('verify-subscription-absent','sns','get-subscription-attributes',{'SubscriptionArn':R['subscription']},strict=False,cleanup=True)
    if 'topic' in R:
        call('delete-topic','sns','delete-topic',{'TopicArn':TOPIC},strict=False,cleanup=True)
        call('verify-topic-absent','sns','get-topic-attributes',{'TopicArn':TOPIC},strict=False,cleanup=True)
    if 'queue' in R:
        call('delete-queue','sqs','delete-queue',{'QueueUrl':R['queue']['url']},strict=False,cleanup=True)
        call('verify-queue-absent','sqs','get-queue-attributes',{'QueueUrl':R['queue']['url'],'AttributeNames':['QueueArn']},strict=False,cleanup=True)
    if 'key' in R:
        call('schedule-key-deletion','kms','schedule-key-deletion',{'KeyId':R['key']['KeyId'],'PendingWindowInDays':7},strict=False,cleanup=True)
        call('verify-key-pending-deletion','kms','describe-key',{'KeyId':R['key']['KeyId']},strict=False,cleanup=True)
    CAP['cleanup_finished_ms']=ms(); save()

if 'key' in R:
    end=CAP.get('delivery_finished_ms',CAP['cleanup_finished_ms'])/1000
    args={'LookupAttributes':[{'AttributeKey':'EventSource','AttributeValue':'kms.amazonaws.com'}],'StartTime':datetime.datetime.fromtimestamp(START-5,datetime.timezone.utc).isoformat(),'EndTime':datetime.datetime.fromtimestamp(end+5,datetime.timezone.utc).isoformat(),'MaxResults':50}
    deadline=time.monotonic()+660; seen=set()
    CAP['cloudtrail']['window']={'start':args['StartTime'],'end':args['EndTime'],'poll_started_ms':ms(),'maximum_poll_seconds':660}
    while True:
        page_args=dict(args)
        while True:
            started=ms(); res=observe('cloudtrail','lookup-events',page_args,ENV); ended=ms()
            lookup={'input':page_args,'request_started_ms':started,'response_observed_ms':ended,'result_code':res['code']}
            if res['code']!='Success':
                lookup['error']=res; CAP['cloudtrail']['lookups'].append(lookup); save(); break
            out=res['output']; lookup['returned_event_count']=len(out.get('Events',[])); lookup['next_token']=out.get('NextToken'); lookup['matched_owned_event_ids']=[]
            for item in out.get('Events',[]):
                event=json.loads(item['CloudTrailEvent'])
                if R['key']['KeyId'] not in json.dumps(event): continue
                lookup['matched_owned_event_ids'].append(event['eventID'])
                if event['eventID'] in seen: continue
                seen.add(event['eventID'])
                ident=event.get('userIdentity',{})
                if ident.get('accessKeyId'):
                    category='AWS_INTERNAL_FAS' if ident.get('invokedBy') in ['sns.amazonaws.com','cloudwatch.amazonaws.com'] or ident.get('type')=='AWSService' else 'CALLER'
                    ident['accessKeyId']='REDACTED_'+category+'_ACCESS_KEY_SHA256_'+hashlib.sha256(ident['accessKeyId'].encode()).hexdigest()[:16]
                CAP['cloudtrail']['events'].append({'first_observed_ms':ended,'lookup_event_id':item.get('EventId'),'event':event})
            CAP['cloudtrail']['lookups'].append(lookup); save()
            if not out.get('NextToken'): break
            page_args=dict(args,NextToken=out['NextToken']); time.sleep(0.6)
        successful={x['event']['eventName'] for x in CAP['cloudtrail']['events'] if not x['event'].get('errorCode') and x['event'].get('requestParameters',{}).get('encryptionContext',{}).get('aws:sns:topicArn')==TOPIC}
        print(json.dumps({'kms_successful_operations':sorted(successful),'owned_events':len(seen),'receipts':len(CAP['receipts'])}),flush=True)
        if {'GenerateDataKey','Decrypt'} <= successful or time.monotonic()>=deadline: break
        time.sleep(min(30,max(0,deadline-time.monotonic())))
    CAP['cloudtrail']['window']['poll_finished_ms']=ms()
    CAP['cloudtrail']['window']['missing_successful_operations']=sorted({'GenerateDataKey','Decrypt'}-successful)
    if CAP['cloudtrail']['window']['missing_successful_operations']: CAP['limitations'].append('Successful KMS operations missing after bounded polling: '+', '.join(CAP['cloudtrail']['window']['missing_successful_operations']))
CAP['probe_source']={'filename':Path(__file__).name,'sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'content':Path(__file__).read_text(),'aws_cli_helper_sha256':hashlib.sha256(Path('scripts/aws/aws_cli.py').read_bytes()).hexdigest()}
CAP['finished_ms']=ms(); save()
print(json.dumps({'fixture':str(OUT),'failure':CAP.get('failure'),'receipts':len(CAP['receipts']),'key_id':R.get('key',{}).get('KeyId')}),flush=True)
